#include <iostream>
#include <vector>
#include <algorithm>
#include <random>

std::vector<int> generate_random_numbers() {
    /*
     * Esta función genera una lista de diez números al azar entre uno y cuarenta
     * sin repetirlos.
     *
     * Returns:
     *      A vector of ten unique random numbers between 1 and 40.
     */
    std::vector<int> random_numbers;
    for (int i = 1; i <= 40; i++) {
        random_numbers.push_back(i);
    }
    std::shuffle(random_numbers.begin(), random_numbers.end(), std::default_random_engine(std::random_device()()));
