use hyper::{Body, Request, Response, Server};
use hyper::service::{make_service_fn, service_fn};
use hyper::client::HttpConnector;
use hyper_tls::HttpsConnector;
use futures::future::{ok, Future};
use std::env;

fn main() {
    let target = env::var("TARGET").unwrap_or_else(|_| "http://localhost:8000".to_string());
    let addr = env::var("ADDR").unwrap_or_else(|_| "127.0.0.1:8080".to_string());

    let make_svc = make_service_fn(move |_conn| {
        let target = target.clone();
        service_fn(move |req: Request<Body>| {
            let uri = req.uri().clone();
            let https = HttpsConnector::new();
            let client = hyper::Client::builder().build::<_, Body>(https);
            client
                .request(req)
                .map(move |res| {
                    let mut new_res = res;
                    new_res.headers_mut().remove("content-length");
                    new_res
                })
                .map_err(|e| {
                    eprintln!("error: {}", e);
                    e
                })
                .and_then(|res| {
                    ok(Response::builder()
                        .status(res.status())
                        .headers(res.headers().clone())
                        .body(res.into_body())
                        .unwrap())
                })
        })
    });

    let server = Server::bind(&addr)
        .serve(make_svc)
        .map_err(|e| eprintln!("server error: {}", e));

    hyper::rt::run(server);
}

Explanation:

    The main function starts by reading the target URL and the address for the reverse proxy from environment variables. If the variables are not set, it defaults to "http://localhost:8000" for the target and "127.0.0.1:8080" for the address.

    The make_service_fn creates a service function that will handle incoming requests. The service function takes a Request object, clones its URI, and sends a request to the target URL using the hyper library.

    The response from the target is then returned as a new response with the content-length header removed.

    Finally, the reverse proxy is started using the Server::bind and serve methods, which bind the reverse proxy to the specified address and start serving incoming requests.

This example shows how to implement a simple reverse proxy in Rust using the hyper library. The reverse proxy takes incoming requests, forwards them to the target URL, and returns the response from the target.

